        if match := web.re_compile(r"(/people/[^/]+)/lists/OL\d+L").match(self.key):
            key = match.group(1)
            return self._site.get(key)
        return None

    def get_cover(self) -> Image | None:
        """Returns a cover object."""
        return self.cover and Image(self._site, "b", self.cover)

    def get_tags(self) -> list[Any]:
        """Returns tags as objects.

        Each tag object will contain name and url fields.
        """
        return [web.storage(name=t, url=self.key + "/tags/" + t) for t in self.tags]

    def _get_subjects(self) -> list[Any]:
        """Returns list of subjects inferred from the seeds.
        Each item in the list will be a storage object with title and url.
        """
        # sample subjects
        return [
            web.storage(title="Cheese", url="/subjects/cheese"),
            web.storage(title="San Francisco", url="/subjects/place:san_francisco"),
        ]

    def add_seed(self, seed: SeedValue) -> bool:
        """Adds a new seed to this list.

        seed can be:
            - author, edition or work object
            - {"key": "..."} for author, edition or work objects
            - subject strings.
        """
        normalized_seed = self._normalize_seed(seed)
        index = self._index_of_seed(normalized_seed)
        if index >= 0:
            return False
        else:
            self.seeds = self.seeds or []
            self.seeds.append(normalized_seed)
            return True

    def remove_seed(self, seed: SeedValue) -> bool:
        """Removes a seed for the list."""
        if (index := self._index_of_seed(self._normalize_seed(seed))) >= 0:
            self.seeds.pop(index)
            return True
        else:
            return False

    def _normalize_seed(self, seed: SeedValue) -> SeedDict | SeedSubjectString:
        if isinstance(seed, Thing):
            key = seed.key
        elif isinstance(seed, dict):
            key = seed["key"]
        else:
            key = str(seed)

        if key.startswith("/subjects/") or is_seed_subject_string(key):
            return normalize_subject_seed(key)
        return {"key": key}

    def _seed_key(self, seed: SeedValue | str | dict[str, Any]) -> str:
        if isinstance(seed, Thing):
            value: SeedValue = seed
        elif isinstance(seed, dict):
            value = {"key": seed["key"]}
        elif isinstance(seed, str) and (
            seed.startswith("/subjects/") or is_seed_subject_string(seed)
        ):
            value = SeedSubjectString(seed)
        elif isinstance(seed, str):
            value = {"key": seed}
        else:
            value = seed

        normalized = self._normalize_seed(value)
        if isinstance(normalized, str):
            return normalized
        return normalized["key"]

    def _index_of_seed(self, seed: SeedValue) -> int:
        seed_key = self._seed_key(seed)
        for i, stored_seed in enumerate(self.seeds or []):
            if self._seed_key(stored_seed) == seed_key:
                return i
        return -1

    def __repr__(self) -> str:
        return f"<List: {self.key} ({self.name!r})>"

    def _get_rawseeds(self) -> list[str]:
        return [self._seed_key(seed) for seed in (self.seeds or [])]

    @cached_property
    def last_update(self) -> datetime | None:
        last_updates = [seed.last_update for seed in self.get_seeds()]
        last_updates = [x for x in last_updates if x]
        if last_updates:
            return max(last_updates)
        else:
            return None

    @property
    def seed_count(self) -> int:
        return len(self.seeds or [])

