    def get_all_editions(self) -> list[dict[str, Any]]:
        """Returns all the editions of this list in arbitrary order.

        The return value is an iterator over all the editions. Each entry is a dictionary.
        (Compare the difference with get_editions.)

        This works even for lists with too many seeds as it doesn't try to
        return editions in the order of last-modified.
        """
        seeds = self.get_seeds()
        edition_keys = {seed.key for seed in seeds if seed.type == "edition"}
        query_terms = [
            f"key:{seed.key.split('/')[-1]}"
            if seed.type == "work"
            else f"author_key:{seed.key.split('/')[-1]}"
            for seed in seeds
            if seed.type in ("work", "author")
        ]
        edition_keys = set(self._get_edition_keys_from_solr(query_terms))

        # Add all editions
        edition_keys.update(
            seed.key for seed in seeds if seed.type == "edition"
        )

        return [doc.dict() for doc in web.ctx.site.get_many(list(edition_keys))]

    def _get_edition_keys_from_solr(
        self, query_terms: list[str]
    ) -> Iterator[str]:
        if not query_terms:
            return
        q = " OR ".join(query_terms)
        solr = get_solr()
        result = solr.select(q, fields=["edition_key"], rows=10000)
        for doc in result["docs"]:
            if 'edition_key' not in doc:
                continue
            for k in doc['edition_key']:
                yield "/books/" + k

    def get_export_list(self) -> ExportList:
        """Returns all the editions, works and authors of this list in arbitrary order.

        Each category contains loaded documents represented as dictionaries.

        This works even for lists with too many seeds as it doesn't try to
        return entries in the order of last-modified.
        """

        seed_types = {
            "edition": ("editions", "/type/edition"),
            "work": ("works", "/type/work"),
            "author": ("authors", "/type/author"),
        }
        keys_by_type: dict[str, set[str]] = {
            "edition": set(),
            "work": set(),
            "author": set(),
        }
        for seed in self.get_seeds():
            if seed.type in seed_types:
                keys_by_type[seed.type].add(seed.key)

        export_list: ExportList = {"authors": [], "works": [], "editions": []}
        for seed_type, (export_key, expected_type) in seed_types.items():
            documents = web.ctx.site.get_many(list(keys_by_type[seed_type]))
            export_list[export_key] = [
                doc.dict()
                for doc in documents
                if doc and doc.type.key == expected_type
            ]
        return export_list

    def _preload(self, keys: Iterable[str]) -> list[Thing]:
        keys = list(set(keys))
        return self._site.get_many(keys)

    def preload_works(self, editions: Iterable[Thing]) -> list[Thing]:
        return self._preload(w.key for e in editions for w in e.get('works', []))

    def preload_authors(self, editions: Iterable[Thing]) -> list[Thing]:
        works = self.preload_works(editions)
        return self._preload(
            a.author.key for w in works for a in w.get("authors", []) if "author" in a
        )

    def load_changesets(self, editions: Iterable[Thing]) -> None:
        """Adds "recent_changeset" to each edition.

        The recent_changeset will be of the form:
            {
            else:
                return "subjects"

        d = web.storage(subjects=[], places=[], people=[], times=[])

        for s in self._get_all_subjects():
            kind = get_subject_type(s)
            if len(d[kind]) < limit:
                d[kind].append(s)
        return d

    def get_seeds(
        self, sort: bool = False, resolve_redirects: bool = False
    ) -> list[Seed]:
        seeds: list[Seed] = []
        for stored_seed in self.seeds or []:
            normalized_seed = self._normalize_seed(stored_seed)
            if isinstance(normalized_seed, str):
                seed_value: SeedValue = normalized_seed
            else:
                seed_value = self._site.get(normalized_seed["key"]) or normalized_seed
            seed = Seed(self, seed_value)
            max_checks = 10
            while (
                resolve_redirects
                and seed.type == "redirect"
                and max_checks
                and seed.document
            ):
                redirected = web.ctx.site.get(seed.document.location)
                if redirected is None:
                    break
                seed = Seed(self, redirected)
                max_checks -= 1
            if seed.type == "subject":
                _ = seed.document
            seeds.append(seed)

        if sort:
            seeds = h.safesort(seeds, reverse=True, key=lambda seed: seed.last_update)

        return seeds

    def get_seed(self, seed: SeedValue) -> Seed:
        normalized_seed = self._normalize_seed(seed)
        if isinstance(normalized_seed, str):
            return Seed(self, normalized_seed)
        document = self._site.get(normalized_seed["key"])
        return Seed(self, document or normalized_seed)

    def has_seed(self, seed: SeedValue) -> bool:
        return self._seed_key(seed) in self._get_rawseeds()

    # cache the default_cover_id for 60 seconds
    @cache.memoize(
        "memcache", key=lambda self: ("d" + self.key, "default-cover-id"), expires=60
    )
    def _get_default_cover_id(self) -> Any:
        for s in self.get_seeds():
            cover = s.get_cover()
            if cover:
                return cover.id

    def get_default_cover(self) -> Image:
        cover_id = self._get_default_cover_id()
        return Image(self._site, 'b', cover_id)


class Seed:
    """Seed of a list.

    Attributes:
        * last_update
        * type - "edition", "work" or "subject"
        * document - reference to the edition/work document
        * title
        * url
        * cover
    """

    def __init__(
        self,
        list: List | list[Any] | tuple[Any, ...],
        value: SeedValue | web.storage,
    ) -> None:
        self._list = list
        self._type = None

        self.value = value
        if isinstance(value, str):
            self.key = value
            self._type = "subject"
        elif isinstance(value, dict):
            self.key = value["key"]
        else:
            self.key = value.key

    @cached_property
    def document(self) -> Any:
        if isinstance(self.value, str):
            return get_subject(self.get_subject_url(self.value))
        elif isinstance(self.value, web.storage):
            return self.value
        elif isinstance(self.value, dict):
            return self._list._site.get(self.value["key"])
        else:
            return self.value

    def get_solr_query_term(self) -> str | None:
        if self.type == "subject":
            typ, value = self.key.split(":", 1)
            # escaping value as it can have special chars like : etc.
            value = get_solr().escape(value)
            return f"{typ}_key:{value}"
        else:
            document = self.document
            if document is None:
                return None
            doc_basekey = document.key.split("/")[-1]
            if self.type == "edition":
                return f"edition_key:{doc_basekey}"
            elif self.type == "work":
                return f'key:/works/{doc_basekey}'
            elif self.type == "author":
                return f"author_key:{doc_basekey}"
            else:
                logger.warning(
                    f"Cannot get solr query term for seed type {self.type}",
                    extra={'list': self._list.key, 'seed': self.key},
                )
                return None

    @cached_property
    def type(self) -> str:
        if self._type:
            return self._type
        document = self.document
        if document is None:
            return self._type_from_key()
        document_type = getattr(document, "type", None)
        key = document_type.get("key") if isinstance(document_type, dict) else None
        if key is None:
            key = getattr(document_type, "key", None)
        if key in ("/type/author", "/type/edition", "/type/redirect", "/type/work"):
            return key.split("/")[-1]
        key_type = self._type_from_key()
        if key_type != "unknown":
            return key_type
        raise AttributeError("Seed document has no recognized Open Library type")

    @property
    def title(self) -> str:
        if self.type in ("work", "edition"):
            return getattr(self.document, "title", None) or self.key
        elif self.type == "author":
            return getattr(self.document, "name", None) or self.key
        elif self.type == "subject":
            return getattr(self.document, "name", None) or self.key.replace("_", " ")
        else:
            return self.key

    @property
    def url(self) -> str:
        document = self.document
        if document and callable(getattr(document, "url", None)):
            return document.url()
        if self.type == "subject":
            return self.get_subject_url(self.key)
        return self.key

    def get_subject_url(self, subject: str) -> str:
        if subject.startswith("subject:"):
            subject = subject.split(":", 1)[1]
        return "/subjects/" + subject

    def get_cover(self) -> Image | None:
        document = self.document
        if document is None:
            return None
        if self.type in ["work", "edition"]:
            return document.get_cover()
        elif self.type == "author":
            return document.get_photo()
        elif self.type == "subject":
            return document.get_default_cover()
        else:
            return None

    @cached_property
    def last_update(self) -> datetime | None:
        document = self.document
        if document is None:
            return None
        last_modified = document.get("last_modified")
        if isinstance(last_modified, dict):
            last_modified = last_modified.get("value")
        if isinstance(last_modified, str):
            return h.parse_datetime(last_modified)
        return last_modified

    def dict(self) -> dict[str, Any]:
        if self.type == "subject":
            url = self.url
            full_url = self.url
        else:
            url = self.key
            full_url = self.url

        d = {
            "url": url,
            "full_url": full_url,
            "type": self.type,
            "title": self.title,
            "last_update": self.last_update and self.last_update.isoformat() or None,
        }
        if cover := self.get_cover():
            d['picture'] = {"url": cover.url("S")}
        return d

    def __repr__(self) -> str:
        return f"<seed: {self.type} {self.key}>"

    __str__ = __repr__

    def _type_from_key(self) -> str:
        if self.key.startswith("/authors/"):
            return "author"
        elif self.key.startswith("/works/"):
            return "work"
        elif self.key.startswith("/books/"):
            return "edition"
        return "unknown"


class ListChangeset(Changeset):
    def get_added_seed(self) -> Seed | None:
        added = self.data.get("add")
        if added and len(added) == 1:
            return self.get_seed(added[0])

    def get_removed_seed(self) -> Seed | None:
        removed = self.data.get("remove")
        if removed and len(removed) == 1:
            return self.get_seed(removed[0])

    def get_list(self) -> List:
        return self.get_changes()[0]

    def get_seed(self, seed: SeedValue | dict[str, Any] | str) -> Seed:
        """Returns the seed object."""
        if isinstance(seed, dict):
            seed = self._site.get(seed["key"]) or seed
        return Seed(self.get_list(), seed)


