def is_seed_subject_string(seed: str) -> TypeGuard[SeedSubjectString]:
    """Return whether ``seed`` starts with a recognized subject type."""
    return seed.startswith(("subject:", "place:", "person:", "time:"))


def subject_key_to_seed(key: str) -> SeedSubjectString:
    """Convert a subject key or path into its normalized seed string."""
    return normalize_subject_seed(key)


@dataclass
class ListRecord:
    key: str | None = None
    name: str = ''
    description: str = ''
    seeds: list[SeedDict | SeedSubjectString] = field(default_factory=list)

    @staticmethod
    def normalize_input_seed(
        seed: SeedDict | str,
    ) -> SeedDict | SeedSubjectString:
        if isinstance(seed, str):
            if seed.startswith("/subjects/") or is_seed_subject_string(seed):
                return subject_key_to_seed(seed)
            else:
                return {'key': seed if seed.startswith('/') else olid_to_key(seed)}
        else:
            if seed["key"].startswith("/subjects/") or is_seed_subject_string(
                seed["key"]
            ):
                return subject_key_to_seed(seed["key"])
            else:
                return seed

    @staticmethod
    def from_input() -> "ListRecord":
        DEFAULTS = {
            'key': None,
            'name': '',
            'description': '',
            'seeds': [],
        }
        if data := web.data():
            # If the requests has data, parse it and use it to populate the list
            if getattr(web.ctx, "env", {}).get("CONTENT_TYPE") == "application/json":
                i = {} | DEFAULTS | json.loads(data)
            else:
                form_data = {
                    # By default all the values are lists
                    k: v[0]
                    for k, v in parse_qs(bytes.decode(data)).items()
                }
                i = {} | DEFAULTS | utils.unflatten(form_data)
        else:
            # Otherwise read from the query string
            i = utils.unflatten(web.input(**DEFAULTS))

        normalized_seeds = [
            ListRecord.normalize_input_seed(seed)
            for seed_list in i['seeds']
            for seed in (
                seed_list.split(',') if isinstance(seed_list, str) else [seed_list]
            )
        ]
        normalized_seeds = [
            seed
            for seed in normalized_seeds
            if seed and (isinstance(seed, str) or seed.get("key"))
        ]
        return ListRecord(
            key=i['key'],
            name=i['name'],
            description=i['description'],
            seeds=normalized_seeds,
        )

    def to_thing_json(self) -> dict[str, Any]:
        return {
            "key": self.key,
            "type": {"key": "/type/list"},
            "name": self.name,
            "description": self.description,
            "seeds": self.seeds,
        }


